mapper.select:
SELECT  FROM jobs WHERE tenant_id=#{tenantId}
AND id<#{cursor}
AND state IN #{state}
ORDER BY id DESC LIMIT #{limit}

SELECT id,tenant_id,actor_id,action,target_type,target_id,outcome,request_id,CAST(details AS CHAR CHARACTER SET utf8mb4) AS detailsText,created_at
FROM audit_logs WHERE tenant_id=#{tenantId}
AND id<#{cursor}AND action=#{action}AND outcome=#{outcome}
ORDER BY id DESC LIMIT #{limit}

SELECT AVG(TIMESTAMPDIFF(MICROSECOND,f.sent,(SELECT MIN(m.created_at) FROM messages m WHERE m.tenant_id=c.tenant_id AND m.conversation_id=c.id AND m.author_role IN('ai','agent') AND m.created_at>=f.sent)))/1000.0
FROM conversations c JOIN (SELECT conversation_id,MIN(created_at) AS sent FROM messages WHERE tenant_id=#{tenantId} AND author_role='customer' GROUP BY conversation_id) f ON f.conversation_id=c.id
WHERE c.tenant_id=#{tenantId} AND c.created_at>=#{start} AND c.created_at<#{end}
